{"command":"create","path":"/workspace/backend/internal/auth/auth.go","file_text":"package auth

import (
	"crypto/rand"
	"encoding/base64"
	"encoding/hex"
	"net/http"
	"strings"
	"time"

	"golang.org/x/crypto/bcrypt"
)

func HashPassword(pw string) (string, error) {
	b, err := bcrypt.GenerateFromPassword([]byte(pw), bcrypt.DefaultCost)
	return string(b), err
}

func CheckPassword(hash, pw string) bool {
	return bcrypt.CompareHashAndPassword([]byte(hash), []byte(pw)) == nil
}

func NewToken() string {
	b := make([]byte, 32)
	_, _ = rand.Read(b)
	return hex.EncodeToString(b)
}

func ExtractBearer(r *http.Request) string {
	h := r.Header.Get("Authorization")
	if h == "" {
		return ""
	}
	parts := strings.SplitN(h, " ", 2)
	if len(parts) != 2 || !strings.EqualFold(parts[0], "Bearer") {
		return ""
	}
	return strings.TrimSpace(parts[1])
}

// ExtractWSToken reads bearer.<token> from websocket subprotocols.
func ExtractWSToken(protocols []string) string {
	for _, p := range protocols {
		if strings.HasPrefix(p, "bearer.") {
			enc := strings.TrimPrefix(p, "bearer.")
			// try raw first
			if dec, err := base64.RawURLEncoding.DecodeString(enc); err == nil && len(dec) > 0 {
				return string(dec)
			}
			if dec, err := base64.URLEncoding.DecodeString(enc); err == nil && len(dec) > 0 {
				return string(dec)
			}
			return enc
		}
	}
	return ""
}

func SessionExpiry() time.Time {
	return time.Now().UTC().Add(24 * time.Hour)
}
"}

{"command":"create","path":"/workspace/backend/internal/handlers/httpx.go","file_text":"package handlers

import (
	"encoding/json"
	"net/http"
	"time"
)

type ctxKey string

const (
	CtxUserID     ctxKey = "userId"
	CtxActiveRole ctxKey = "activeRole"
	CtxRoles      ctxKey = "roles"
	CtxUsername   ctxKey = "username"
)

func writeJSON(w http.ResponseWriter, status int, v interface{}) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}

func writeData(w http.ResponseWriter, status int, data interface{}) {
	writeJSON(w, status, map[string]interface{}{"data": data})
}

func writeError(w http.ResponseWriter, status int, code, msg string) {
	writeJSON(w, status, map[string]string{"error": msg, "code": code})
}

func decodeJSON(r *http.Request, dst interface{}) error {
	dec := json.NewDecoder(r.Body)
	dec.DisallowUnknownFields()
	return dec.Decode(dst)
}

func parseTime(s string) (time.Time, error) {
	if s == "" {
		return time.Time{}, nil
	}
	formats := []string{
		time.RFC3339Nano,
		time.RFC3339,
		"2006-01-02T15:04:05Z07:00",
		"2006-01-02T15:04:05.000Z",
		"2006-01-02T15:04:05",
	}
	var err error
	for _, f := range formats {
		var t time.Time
		t, err = time.Parse(f, s)
		if err == nil {
			return t.UTC(), nil
		}
	}
	return time.Time{}, err
}

func ptrStr(s string) *string {
	if s == "" {
		return nil
	}
	return &s
}

func strOrEmpty(p *string) string {
	if p == nil {
		return ""
	}
	return *p
}

func contains(ss []string, x string) bool {
	for _, s := range ss {
		if s == x {
			return true
		}
	}
	return false
}

func roleAllowed(active string, allowed ...string) bool {
	if active == "administrator" {
		// admin can do dispatcher things but must select role for role-gated ops
		for _, a := range allowed {
			if a == "administrator" {
				return true
			}
		}
	}
	for _, a := range allowed {
		if active == a {
			return true
		}
	}
	return false
}

func isDispatcherLike(role string) bool {
	return role == "administrator" || role == "dispatcher"
}
"}

{"command":"create","path":"/workspace/backend/internal/service/service.go","file_text":"package service

import (
	"context"
	"database/sql"
	"encoding/json"
	"fmt"
	"math"
	"strings"
	"sync"
	"time"

	"lablogistics/internal/auth"
	"lablogistics/internal/config"
	"lablogistics/internal/db"
	"lablogistics/internal/models"

	"github.com/google/uuid"
	"go.mongodb.org/mongo-driver/bson"
)

type Service struct {
	DB     *db.DB
	Cfg    config.Config
	mu     sync.Mutex
	hub    *EventHub
	offerT time.Duration
}

func New(d *db.DB, cfg config.Config) *Service {
	s := &Service{
		DB:     d,
		Cfg:    cfg,
		hub:    NewEventHub(),
		offerT: 2 * time.Minute,
	}
	return s
}

func (s *Service) Hub() *EventHub { return s.hub }

// ---------- errors ----------

type AppError struct {
	Status  int
	Code    string
	Message string
}

func (e *AppError) Error() string { return e.Message }

func Err(status int, code, msg string) *AppError {
	return &AppError{Status: status, Code: code, Message: msg}
}

// ---------- bootstrap ----------

func (s *Service) EnsureAdmin() error {
	var count int
	if err := s.DB.SQL.QueryRow(`SELECT COUNT(*) FROM users`).Scan(&count); err != nil {
		return err
	}
	if count > 0 {
		return nil
	}
	hash, err := auth.HashPassword(s.Cfg.AdminPassword)
	if err != nil {
		return err
	}
	roles, _ := json.Marshal([]string{models.RoleAdministrator})
	_, err = s.DB.SQL.Exec(`
		INSERT INTO users (username, password_hash, full_name, roles, qualifications, certifications, active)
		VALUES ($1,$2,'System Administrator',$3,'[]','[]',TRUE)`,
		s.Cfg.AdminUsername, hash, roles)
	if err != nil {
		return err
	}
	return s.EnsureDefaultSampleTypes()
}

func (s *Service) EnsureDefaultSampleTypes() error {
	defaults := []struct {
		name, qual, container string
		tmin, tmax            float64
		cooled, batch         bool
	}{
		{"Amber", "Amber", "standard", 2, 25, false, true},
		{"Indigo", "Indigo", "standard", 2, 25, false, true},
		{"Frost", "Frost", "cooled", 2, 8, true, true},
		{"Pulse", "Pulse", "express", 2, 25, false, false},
	}
	for _, d := range defaults {
		var exists int
		_ = s.DB.SQL.QueryRow(`SELECT COUNT(*) FROM sample_types WHERE name=$1`, d.name).Scan(&exists)
		if exists > 0 {
			continue
		}
		_, err := s.DB.SQL.Exec(`
			INSERT INTO sample_types (name, qualified_collector_required, required_qualification, container_type,
				temperature_min_c, temperature_max_c, incompatible_sample_types, requires_cooled_route, batching_allowed)
			VALUES ($1,TRUE,$2,$3,$4,$5,'[]',$6,$7)`,
			d.name, d.qual, d.container, d.tmin, d.tmax, d.cooled, d.batch)
		if err != nil {
			return err
		}
	}
	// Indigo incompatible with Amber
	var amberID, indigoID string
	_ = s.DB.SQL.QueryRow(`SELECT id::text FROM sample_types WHERE name='Amber'`).Scan(&amberID)
	_ = s.DB.SQL.QueryRow(`SELECT id::text FROM sample_types WHERE name='Indigo'`).Scan(&indigoID)
	if amberID != "" && indigoID != "" {
		inc, _ := json.Marshal([]string{amberID})
		_, _ = s.DB.SQL.Exec(`UPDATE sample_types SET incompatible_sample_types=$1 WHERE id=$2::uuid`, inc, indigoID)
		inc2, _ := json.Marshal([]string{indigoID})
		_, _ = s.DB.SQL.Exec(`UPDATE sample_types SET incompatible_sample_types=$1 WHERE id=$2::uuid`, inc2, amberID)
	}
	return s.rebuildServiceability()
}

// ---------- auth ----------

type SessionInfo struct {
	UserID     string
	Username   string
	FullName   string
	Roles      []string
	ActiveRole string
	Token      string
}

func (s *Service) Authenticate(username, password string) (*SessionInfo, error) {
	var id, hash, fullName string
	var rolesJSON []byte
	var active bool
	err := s.DB.SQL.QueryRow(`
		SELECT id::text, password_hash, full_name, roles, active FROM users WHERE username=$1`, username).
		Scan(&id, &hash, &fullName, &rolesJSON, &active)
	if err == sql.ErrNoRows {
		return nil, Err(401, "invalid_credentials", "invalid credentials")
	}
	if err != nil {
		return nil, err
	}
	if !active {
		return nil, Err(401, "invalid_credentials", "account inactive")
	}
	if !auth.CheckPassword(hash, password) {
		_ = s.Audit("", "", "auth.login", "user", id, false, map[string]interface{}{"username": username})
		return nil, Err(401, "invalid_credentials", "invalid credentials")
	}
	roles := models.ParseStringSlice(rolesJSON)
	activeRole := ""
	if len(roles) == 1 {
		activeRole = roles[0]
	}
	token := auth.NewToken()
	_, err = s.DB.SQL.Exec(`INSERT INTO sessions (token, user_id, active_role, expires_at) VALUES ($1,$2::uuid,$3,$4)`,
		token, id, activeRole, auth.SessionExpiry())
	if err != nil {
		return nil, err
	}
	_ = s.Audit(id, activeRole, "auth.login", "user", id, true, map[string]interface{}{"username": username})
	return &SessionInfo{UserID: id, Username: username, FullName: fullName, Roles: roles, ActiveRole: activeRole, Token: token}, nil
}

func (s *Service) ResolveSession(token string) (*SessionInfo, error) {
	if token == "" {
		return nil, Err(401, "unauthorized", "unauthorized")
	}
	var id, username, fullName, activeRole string
	var rolesJSON []byte
	var expires time.Time
	var active bool
	err := s.DB.SQL.QueryRow(`
		SELECT u.id::text, u.username, u.full_name, u.roles, u.active, s.active_role, s.expires_at
		FROM sessions s JOIN users u ON u.id = s.user_id
		WHERE s.token=$1`, token).
		Scan(&id, &username, &fullName, &rolesJSON, &active, &activeRole, &expires)
	if err == sql.ErrNoRows {
		return nil, Err(401, "unauthorized", "unauthorized")
	}
	if err != nil {
		return nil, err
	}
	if !active || time.Now().UTC().After(expires) {
		return nil, Err(401, "unauthorized", "session expired")
	}
	return &SessionInfo{
		UserID: id, Username: username, FullName: fullName,
		Roles: models.ParseStringSlice(rolesJSON), ActiveRole: activeRole, Token: token,
	}, nil
}

func (s *Service) SelectRole(userID, role string, userRoles []string) (string, []string, error) {
	if !contains(userRoles, role) {
		return "", nil, Err(400, "invalid_role", "role not assigned to user")
	}
	_, err := s.DB.SQL.Exec(`UPDATE sessions SET active_role=$1 WHERE user_id=$2::uuid`, role, userID)
	if err != nil {
		return "", nil, err
	}
	_ = s.Audit(userID, role, "auth.select_role", "user", userID, true, map[string]interface{}{"role": role})
	return role, userRoles, nil
}

// ---------- idempotency ----------

func (s *Service) Idempotent(userID, key, op string, fn func() (int, interface{}, error)) (int, interface{}, error) {
	if key == "" {
		return 0, nil, Err(400, "idempotency_required", "idempotencyKey is required")
	}
	var status int
	var body []byte
	err := s.DB.SQL.QueryRow(`
		SELECT response_status, response_body FROM idempotency_keys
		WHERE key=$1 AND user_id=$2::uuid AND operation=$3`, key, userID, op).Scan(&status, &body)
	if err == nil {
		var v interface{}
		_ = json.Unmarshal(body, &v)
		return status, v, nil
	}
	if err != sql.ErrNoRows {
		return 0, nil, err
	}
	st, resp, err := fn()
	if err != nil {
		return 0, nil, err
	}
	b, _ := json.Marshal(resp)
	_, _ = s.DB.SQL.Exec(`
		INSERT INTO idempotency_keys (key, user_id, operation, response_status, response_body)
		VALUES ($1,$2::uuid,$3,$4,$5)
		ON CONFLICT DO NOTHING`, key, userID, op, st, b)
	return st, resp, nil
}

