var upgrader = websocket.Upgrader{CheckOrigin: func(r *http.Request) bool { return true }}

func (a *API) EventsWS(w http.ResponseWriter, r *http.Request) {
	// auth via subprotocol or query
	token := auth.ExtractBearer(r)
	if token == "" {
		token = auth.ExtractWSToken(websocket.Subprotocols(r))
	}
	if token == "" {
		token = r.URL.Query().Get("token")
	}
	sess, err := a.Svc.ResolveSession(token)
	if err != nil {
		writeError(w, 401, "unauthorized", "unauthorized")
		return
	}
	since := int64(0)
	if s := r.URL.Query().Get("since"); s != "" {
		since, _ = strconv.ParseInt(s, 10, 64)
	}

	conn, err := upgrader.Upgrade(w, r, nil)
	if err != nil {
		return
	}
	defer conn.Close()

	// replay
	for _, ev := range a.Svc.EventsSince(since) {
		_ = conn.WriteJSON(map[string]interface{}{
			"id": ev.ID, "type": ev.Type, "entityType": ev.EntityType,
			"entityId": ev.EntityID, "payload": ev.Payload, "createdAt": ev.CreatedAt,
		})
	}

	ch := a.Svc.Hub().Subscribe(sess.ActiveRole)
	defer a.Svc.Hub().Unsubscribe(ch)

	done := make(chan struct{})
	go func() {
		defer close(done)
		for {
			if _, _, err := conn.ReadMessage(); err != nil {
				return
			}
		}
	}()

	ticker := time.NewTicker(30 * time.Second)
	defer ticker.Stop()
	for {
		select {
		case <-done:
			return
		case ev, ok := <-ch:
			if !ok {
				return
			}
			if err := conn.WriteJSON(map[string]interface{}{
				"id": ev.ID, "type": ev.Type, "entityType": ev.EntityType,
				"entityId": ev.EntityID, "payload": ev.Payload, "createdAt": ev.CreatedAt,
			}); err != nil {
				return
			}
		case <-ticker.C:
			if err := conn.WriteControl(websocket.PingMessage, []byte("ping"), time.Now().Add(5*time.Second)); err != nil {
				return
			}
		}
	}
}

func toF(v interface{}) float64 {
	switch t := v.(type) {
	case float64:
		return t
	case int:
		return float64(t)
	case json.Number:
		f, _ := t.Float64()
		return f
	}
	return 0
}
"}

{"command":"create","path":"/workspace/backend/cmd/server/main.go","file_text":"package main

import (
	"log"
	"net/http"
	"os"
	"os/signal"
	"path/filepath"
	"syscall"
	"time"

	"lablogistics/internal/config"
	"lablogistics/internal/db"
	"lablogistics/internal/handlers"
	"lablogistics/internal/service"
)

func main() {
	cfg := config.Load()

	schemaPath := os.Getenv("SCHEMA_PATH")
	if schemaPath == "" {
		// try common locations
		candidates := []string{
			"/workspace/backend/internal/db/schema.sql",
			"internal/db/schema.sql",
			filepath.Join(filepath.Dir(os.Args[0]), "schema.sql"),
		}
		for _, c := range candidates {
			if _, err := os.Stat(c); err == nil {
				schemaPath = c
				break
			}
		}
	}
	if schemaPath == "" {
		log.Fatal("SCHEMA_PATH not found")
	}

	database, err := db.Connect(cfg.DatabaseURL, cfg.MongoURI, cfg.MongoDB)
	if err != nil {
		log.Fatalf("database connect: %v", err)
	}
	defer database.Close()

	if err := database.Migrate(schemaPath); err != nil {
		log.Fatalf("migrate: %v", err)
	}

	svc := service.New(database, cfg)
	if err := svc.EnsureAdmin(); err != nil {
		log.Fatalf("ensure admin: %v", err)
	}
	if err := svc.EnsureDefaultSampleTypes(); err != nil {
		log.Fatalf("ensure sample types: %v", err)
	}

	api := handlers.New(svc)
	handler := api.Router(cfg.StaticDir, cfg.MapAssetsDir)

	srv := &http.Server{
		Addr:              cfg.HTTPAddr,
		Handler:           handler,
		ReadHeaderTimeout: 10 * time.Second,
		ReadTimeout:       60 * time.Second,
		WriteTimeout:      120 * time.Second,
		IdleTimeout:       120 * time.Second,
	}

	go func() {
		log.Printf("lab logistics listening on %s", cfg.HTTPAddr)
		if err := srv.ListenAndServe(); err != nil && err != http.ErrServerClosed {
			log.Fatalf("listen: %v", err)
		}
	}()

	stop := make(chan os.Signal, 1)
	signal.Notify(stop, syscall.SIGINT, syscall.SIGTERM)
	<-stop
	log.Printf("shutting down")
	_ = srv.Close()
}
"}

{"command":"str_replace","path":"/workspace/backend/internal/handlers/handlers.go","old_str":"func spaHandler(staticDir string) http.Handler {
	fs := http.FileServer(http.Dir(staticDir))
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		path := staticDir + r.URL.Path
		if r.URL.Path == "/" || strings.HasPrefix(r.URL.Path, "/assets") || fileExists(path) {
			fs.ServeHTTP(w, r)
			return
		}
		http.ServeFile(w, r, staticDir+"/index.html")
	})
}

func fileExists(p string) bool {
	f, err := http.Dir("/").Open(strings.TrimPrefix(p, "/"))
	if err != nil {
		// try direct
		if st, err2 := http.Dir(p).Open("."); err2 == nil {
			_ = st.Close()
			return true
		}
		return false
	}
	_ = f.Close()
	return true
}","new_str":"func spaHandler(staticDir string) http.Handler {
	fs := http.FileServer(http.Dir(staticDir))
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		// try exact file
		p := filepath.Join(staticDir, filepath.Clean(r.URL.Path))
		if info, err := os.Stat(p); err == nil && !info.IsDir() {
			fs.ServeHTTP(w, r)
			return
		}
		// assets directory
		if strings.HasPrefix(r.URL.Path, "/assets/") {
			fs.ServeHTTP(w, r)
			return
		}
		http.ServeFile(w, r, filepath.Join(staticDir, "index.html"))
	})
}"}

