{"command":"create","path":"/workspace/frontend/src/App.tsx","file_text":"import React, { useCallback, useEffect, useMemo, useState } from 'react'
import {
  ApiError, AuthAPI, OpsAPI, SessionUser, clearSession, getStoredUser, saveSession,
} from './api/client'
import MapView from './components/MapView'

type View =
  | 'work'
  | 'requests'
  | 'serviceability'
  | 'sample'
  | 'monitor'
  | 'audit'
  | 'capacity'
  | 'location'
  | 'admin'

const ROLE_LABELS: Record<string, string> = {
  administrator: 'Administrator',
  dispatcher: 'Dispatcher',
  requester: 'Requester',
  collection_professional: 'Collection professional',
  delivery_partner: 'Relay courier',
  node_handler: 'Node handler',
  laboratory_team: 'Laboratory intake',
}

function roleLabel(r: string) {
  return ROLE_LABELS[r] || r
}

function nowIso() {
  return new Date().toISOString()
}

function uid() {
  return crypto.randomUUID()
}

export default function App() {
  const [user, setUser] = useState<SessionUser | null>(getStoredUser())
  const [view, setView] = useState<View>('work')
  const [error, setError] = useState('')
  const [notice, setNotice] = useState('')
  const [bootstrap, setBootstrap] = useState<any>(null)
  const [work, setWork] = useState<any>(null)
  const [ops, setOps] = useState<any>(null)
  const [audit, setAudit] = useState<any>(null)
  const [auditQuery, setAuditQuery] = useState('')
  const [sampleId, setSampleId] = useState('')
  const [sample, setSample] = useState<any>(null)
  const [lifecycle, setLifecycle] = useState<any>(null)
  const [busy, setBusy] = useState(false)

  const activeRole = user?.activeRole || ''

  const refreshBootstrap = useCallback(async () => {
    if (!user) return
    try {
      const data = await AuthAPI.bootstrap()
      setBootstrap(data)
      if (data?.user) {
        const next = {
          ...user,
          roles: data.user.roles || user.roles,
          activeRole: data.user.activeRole || user.activeRole,
          fullName: data.user.fullName || user.fullName,
          username: data.user.username || user.username,
          userId: data.user.userId || user.userId,
        }
        setUser(next)
        saveSession(next)
      }
    } catch (e: any) {
      if (e instanceof ApiError && e.status === 401) {
        clearSession()
        setUser(null)
      }
    }
  }, [user])

  const refreshWork = useCallback(async () => {
    if (!user) return
    try {
      const data = await OpsAPI.listWork(user.activeRole || undefined)
      setWork(data)
    } catch (e: any) {
      setError(e.message || 'Failed to load work')
    }
  }, [user])

  const refreshOps = useCallback(async () => {
    if (!user) return
    try {
      const data = await OpsAPI.operations({})
      setOps(data)
    } catch (e: any) {
      /* ignore if forbidden */
    }
  }, [user])

  useEffect(() => {
    if (!user) return
    refreshBootstrap()
    refreshWork()
    refreshOps()
  }, [user?.sessionToken, user?.activeRole])

  async function handleLogin(username: string, password: string) {
    setError('')
    setBusy(true)
    try {
      const data = await AuthAPI.login(username, password)
      const session: SessionUser = {
        sessionToken: data.sessionToken,
        userId: data.userId,
        roles: data.roles || [],
        activeRole: data.activeRole || (data.roles?.[0] || ''),
        username,
      }
      saveSession(session)
      setUser(session)
      setView('work')
      setNotice('Signed in')
    } catch (e: any) {
      setError(e.message || 'Invalid credentials')
    } finally {
      setBusy(false)
    }
  }

  async function handleLogout() {
    clearSession()
    setUser(null)
    setBootstrap(null)
    setWork(null)
    setOps(null)
    setSample(null)
    setNotice('Signed out')
  }

  async function handleRoleChange(role: string) {
    setError('')
    try {
      const data = await AuthAPI.selectRole(role)
      if (!user) return
      const next = { ...user, activeRole: data.activeRole || role, roles: data.roles || user.roles }
      saveSession(next)
      setUser(next)
      setNotice(`Working as ${roleLabel(role)}`)
      await refreshWork()
    } catch (e: any) {
      setError(e.message || 'Could not switch role')
    }
  }

  async function loadSample(id: string) {
    if (!id) return
    setError('')
    setSampleId(id)
    try {
      const [st, life] = await Promise.all([
        OpsAPI.sampleState(id),
        OpsAPI.sampleLifecycle(id),
      ])
      setSample(st)
      setLifecycle(life)
      setView('sample')
    } catch (e: any) {
      setError(e.message || 'Sample not found')
    }
  }

  async function searchAudit(q = auditQuery) {
    setError('')
    try {
      const data = await OpsAPI.audit({
        query: q || undefined,
        limit: 50,
        order: 'desc',
      })
      setAudit(data)
      setView('audit')
    } catch (e: any) {
      setError(e.message || 'Audit search failed')
    }
  }

  if (!user) {
    return <LoginPage onLogin={handleLogin} error={error} busy={busy} />
  }

  const nav: { id: View; label: string; roles?: string[] }[] = [
    { id: 'work', label: 'My work' },
    { id: 'requests', label: 'New request', roles: ['requester', 'administrator'] },
    { id: 'serviceability', label: 'Serviceability', roles: ['requester', 'dispatcher', 'administrator'] },
    { id: 'sample', label: 'Sample tracking' },
    { id: 'monitor', label: 'Operations', roles: ['dispatcher', 'administrator'] },
    { id: 'audit', label: 'Audit', roles: ['dispatcher', 'administrator'] },
    { id: 'capacity', label: 'Capacity', roles: ['node_handler', 'laboratory_team', 'administrator', 'dispatcher'] },
    { id: 'location', label: 'My location', roles: ['collection_professional', 'delivery_partner', 'node_handler', 'laboratory_team'] },
    { id: 'admin', label: 'Admin', roles: ['administrator'] },
  ]

  const visibleNav = nav.filter(n => !n.roles || n.roles.includes(activeRole) || activeRole === 'administrator')

  return (
    <div className="app-shell">
      <header className="topbar">
        <h1>Lab Sample Pickup & Delivery</h1>
        <div className="meta">
          <span aria-label="signed-in user">{user.fullName || user.username || user.userId}</span>
          <label htmlFor="role-switch" className="muted" style={{ color: 'white' }}>Active role</label>
          <select
            id="role-switch"
            className="role-select"
            aria-label="Select active role"
            value={activeRole}
            onChange={e => handleRoleChange(e.target.value)}
          >
            {(user.roles || []).map(r => (
              <option key={r} value={r}>{roleLabel(r)}</option>
            ))}
          </select>
          <button type="button" className="secondary" onClick={handleLogout} aria-label="Sign out">Sign out</button>
        </div>
      </header>
      <div className="layout">
        <nav className="side" aria-label="Primary">
          {visibleNav.map(n => (
            <button
              key={n.id}
              type="button"
              className={view === n.id ? 'active' : ''}
              onClick={() => {
                setView(n.id)
                if (n.id === 'work') refreshWork()
                if (n.id === 'monitor') refreshOps()
                if (n.id === 'audit') searchAudit()
              }}
            >
              {n.label}
            </button>
          ))}
        </nav>
        <main>
          {error && <div className="error" role="alert">{error}</div>}
          {notice && <div className="success" role="status">{notice}</div>}

          {view === 'work' && (
            <WorkView
              work={work}
              role={activeRole}
              onRefresh={refreshWork}
              onOpenSample={loadSample}
              onAccept={async (assignmentId) => {
                setError('')
                try {
                  await OpsAPI.accept(assignmentId, uid())
                  setNotice('Assignment accepted')
                  await refreshWork()
                } catch (e: any) {
                  setError(e.message)
                }
              }}
              onDecline={async (assignmentId) => {
                setError('')
                try {
                  await OpsAPI.decline(assignmentId, uid())
                  setNotice('Assignment declined')
                  await refreshWork()
                } catch (e: any) {
                  setError(e.message)
                }
              }}
            />
          )}

          {view === 'requests' && (
            <RequestForm
              userId={user.userId}
              sampleTypes={bootstrap?.sampleTypes || ops?.sampleTypes || []}
              onCreated={(res) => {
                setNotice(`Request created: sample ${res.sampleId}`)
                if (res.sampleId) loadSample(res.sampleId)
              }}
              onError={setError}
            />
          )}

          {view === 'serviceability' && (
            <ServiceabilityForm
              sampleTypes={bootstrap?.sampleTypes || ops?.sampleTypes || []}
              onError={setError}
            />
          )}

          {view === 'sample' && (
            <SampleView
              sampleId={sampleId}
              sample={sample}
              lifecycle={lifecycle}
              onLoad={loadSample}
              setSampleId={setSampleId}
            />
          )}

          {view === 'monitor' && (
            <MonitorView ops={ops} onRefresh={refreshOps} onOpenSample={loadSample} />
          )}

          {view === 'audit' && (
            <AuditView
              audit={audit}
              query={auditQuery}
              setQuery={setAuditQuery}
              onSearch={() => searchAudit()}
            />
          )}

          {view === 'capacity' && (
            <CapacityView
              ops={ops}
              bootstrap={bootstrap}
              onSaved={() => { setNotice('Capacity updated'); refreshOps() }}
              onError={setError}
            />
          )}

          {view === 'location' && (
            <LocationView
              work={work}
              onSaved={() => setNotice('Location recorded')}
              onError={setError}
            />
          )}

          {view === 'admin' && (
            <AdminView bootstrap={bootstrap} ops={ops} onRefresh={() => { refreshBootstrap(); refreshOps() }} onError={setError} onNotice={setNotice} />
          )}
        </main>
      </div>
    </div>
  )
}

function LoginPage({ onLogin, error, busy }: { onLogin: (u: string, p: string) => void; error: string; busy: boolean }) {
  const [username, setUsername] = useState('')
  const [password, setPassword] = useState('')
  return (
    <div className="login-wrap">
      <form
        className="login-card"
        aria-label="Sign in"
        onSubmit={e => {
          e.preventDefault()
          onLogin(username, password)
        }}
      >
        <h1>Sign in</h1>
        <p className="muted">Lab sample pickup and delivery network</p>
        {error && <div className="error" role="alert">{error}</div>}
        <label htmlFor="username">Username</label>
        <input id="username" name="username" autoComplete="username" value={username} onChange={e => setUsername(e.target.value)} required />
        <label htmlFor="password">Password</label>
        <input id="password" name="password" type="password" autoComplete="current-password" value={password} onChange={e => setPassword(e.target.value)} required />
        <div className="form-actions">
          <button type="submit" disabled={busy} aria-label="Sign in">{busy ? 'Signing in…' : 'Sign in'}</button>
        </div>
      </form>
    </div>
  )
}

function WorkView({ work, role, onRefresh, onOpenSample, onAccept, onDecline }: any) {
  const current = work?.current || work?.currentWork || work?.items || []
  const past = work?.past || work?.pastWork || work?.completed || []
  const currentList = Array.isArray(current) ? current : (current.assignments || current.samples || [])
  const pastList = Array.isArray(past) ? past : (past.assignments || past.samples || [])

  function renderItem(item: any, done = false) {
    const id = item.assignmentId || item.sampleId || item.id || item.workItemId
    const title = item.title || item.assignmentType || item.status || 'Work item'
    const sampleId = item.sampleId || item.sample_id
    return (
      <div className="work-card" key={id || Math.random()}>
        <header>
          <strong>{title}</strong>
          <span className={`badge ${done ? 'ok' : 'warn'}`}>{item.status || (done ? 'completed' : 'current')}</span>
        </header>
        <div className="muted">
          {item.assignmentId && <div>Assignment: {item.assignmentId}</div>}
          {sampleId && <div>Sample: {sampleId}</div>}
          {item.locationName && <div>Location: {item.locationName}</div>}
          {item.offeredTo && <div>Offered to: {item.offeredTo}</div>}
        </div>
        <div className="form-actions" style={{ marginTop: 8 }}>
          {sampleId && <button type="button" className="secondary" onClick={() => onOpenSample(sampleId)}>Open sample</button>}
          {!done && item.assignmentId && (item.status === 'offered' || item.canAccept) && (
            <>
              <button type="button" onClick={() => onAccept(item.assignmentId)} aria-label="Accept assignment">Accept</button>
              <button type="button" className="secondary" onClick={() => onDecline(item.assignmentId)} aria-label="Decline assignment">Decline</button>
            </>
          )}
        </div>
      </div>
    )
  }

  // Also flatten RoleWork shape
  const currentItems = useMemo(() => {
    if (!work) return []
    if (Array.isArray(work)) return work
    const out: any[] = []
    const pushAll = (x: any) => {
      if (!x) return
      if (Array.isArray(x)) out.push(...x)
      else if (typeof x === 'object') {
        for (const k of ['assignments', 'samples', 'journeys', 'items', 'current', 'offered', 'active']) {
          if (Array.isArray(x[k])) out.push(...x[k])
        }
        if (x.assignmentId || x.sampleId) out.push(x)
      }
    }
    pushAll(work.current)
    pushAll(work.currentWork)
    pushAll(work.offered)
    pushAll(work.active)
    pushAll(work.items)
    if (out.length === 0 && work.assignments) pushAll(work.assignments)
    return out
  }, [work])

  const pastItems = useMemo(() => {
    if (!work) return []
    const out: any[] = []
    const src = work.past || work.pastWork || work.completed || []
    if (Array.isArray(src)) return src
    if (src.assignments) return src.assignments
    if (src.items) return src.items
    return out
  }, [work])

  return (
    <div className="stack">
      <div className="panel">
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <h2>Current work — {roleLabel(role)}</h2>
          <button type="button" className="secondary" onClick={onRefresh}>Refresh</button>
        </div>
        <p className="muted">Assignments and samples you are responsible for in the selected role.</p>
        <div className="card-list" aria-label="Current work">
          {currentItems.length === 0 && <div className="empty">No current work</div>}
          {currentItems.map((it: any, i: number) => renderItem(it, false) || <div key={i} />)}
        </div>
      </div>
      <div className="panel">
        <h2>Past work</h2>
        <div className="card-list" aria-label="Past work">
          {pastItems.length === 0 && <div className="empty">No completed work yet</div>}
          {pastItems.map((it: any, i: number) => (
            <div key={it.assignmentId || it.sampleId || i}>{renderItem(it, true)}</div>
          ))}
        </div>
      </div>
    </div>
  )
}

function RequestForm({ userId, sampleTypes, onCreated, onError }: any) {
  const [originType, setOriginType] = useState('home')
  const [lat, setLat] = useState('51.5074')
  const [lng, setLng] = useState('-0.1278')
  const [sampleTypeId, setSampleTypeId] = useState('')
  const [deadline, setDeadline] = useState(() => new Date(Date.now() + 6 * 3600e3).toISOString().slice(0, 16))
  const [earliest, setEarliest] = useState(() => new Date().toISOString().slice(0, 16))
  const [latest, setLatest] = useState(() => new Date(Date.now() + 2 * 3600e3).toISOString().slice(0, 16))
  const [container, setContainer] = useState('standard')
  const [tmin, setTmin] = useState('2')
  const [tmax, setTmax] = useState('25')
  const [formError, setFormError] = useState('')

  useEffect(() => {
    if (!sampleTypeId && sampleTypes?.length) setSampleTypeId(sampleTypes[0].sampleTypeId || sampleTypes[0].id)
  }, [sampleTypes])

  async function submit(e: React.FormEvent) {
    e.preventDefault()
    setFormError('')
    if (!sampleTypeId) {
      setFormError('Sample type is required')
      onError('Sample type is required')
      return
    }
    if (!lat || !lng) {
      setFormError('Origin coordinates are required')
      onError('Origin coordinates are required')
      return
    }
    try {
      const body = {
        requesterId: userId,
        origin: { latitude: parseFloat(lat), longitude: parseFloat(lng) },
        originType,
        requestedAt: nowIso(),
        deliveryDeadline: new Date(deadline).toISOString(),
        earliestCollectionAt: new Date(earliest).toISOString(),
        latestCollectionAt: new Date(latest).toISOString(),
        sampleTypeId,
        containerType: container,
        temperatureMinC: parseFloat(tmin),
        temperatureMaxC: parseFloat(tmax),
        incompatibleSampleTypes: [],
        idempotencyKey: uid(),
      }
      const res = await OpsAPI.createRequest(body)
      onCreated(res)
    } catch (err: any) {
      setFormError(err.message || 'Could not create request')
      onError(err.message || 'Could not create request')
    }
  }

  return (
    <div className="panel">
      <h2>Create collection request</h2>
      {formError && <div className="error" role="alert">{formError}</div>}
      <form aria-label="Create collection request" onSubmit={submit}>
        <div className="grid-2">
          <div>
            <label htmlFor="originType">Origin type</label>
            <select id="originType" value={originType} onChange={e => setOriginType(e.target.value)}>
              <option value="home">Home</option>
              <option value="clinic">Clinic</option>
              <option value="node">Network node</option>
            </select>
          </div>
          <div>
            <label htmlFor="sampleType">Sample type</label>
            <select id="sampleType" aria-label="Sample type" value={sampleTypeId} onChange={e => setSampleTypeId(e.target.value)} required>
              <option value="">Select…</option>
              {(sampleTypes || []).map((t: any) => (
                <option key={t.sampleTypeId || t.id} value={t.sampleTypeId || t.id}>{t.name}</option>
              ))}
            </select>
          </div>
          <div>
            <label htmlFor="lat">Latitude</label>
            <input id="lat" value={lat} onChange={e => setLat(e.target.value)} required />
          </div>
          <div>
            <label htmlFor="lng">Longitude</label>
            <input id="lng" value={lng} onChange={e => setLng(e.target.value)} required />
          </div>
          <div>
            <label htmlFor="earliest">Earliest collection</label>
            <input id="earliest" type="datetime-local" value={earliest} onChange={e => setEarliest(e.target.value)} />
          </div>
